{"path": "/tmp/sv-005e3806902044378786cf2b9cb3e228/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "@if (TotalPages > 1)
{
    <nav class="catalog-pagination" aria-label="Product pagination">
        <button class="btn-page" disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)">
            Previous
        </button>

        @foreach (var page in GetPageNumbers())
        {
            <button class="btn-page @(page == CurrentPage ? "active" : "")"
                    @onclick="() => GoToPage(page)">
                @page
            </button>
        }

        <button class="btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="() => GoToPage(CurrentPage + 1)">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; } = 1;

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; } = 12;

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages && page != CurrentPage)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 7;
        if (TotalPages <= maxVisible)
        {
            return Enumerable.Range(1, TotalPages);
        }

        var pages = new List<int>();
        int start = Math.Max(1, CurrentPage - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        if (end - start + 1 < maxVisible)
        {
            start = Math.Max(1, end - maxVisible + 1);
        }

        for (int i = start; i <= end; i++)
        {
            pages.Add(i);
        }
        return pages;
    }
}
"}

{"path": "/tmp/sv-005e3806902044378786cf2b9cb3e228/Components/Pages/Catalog/Catalog.razor", "file_text": "@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div class="catalog-error">
        <p>Something went wrong: @_error</p>
        <button @onclick="LoadInitialDataAsync">Try Again</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <CatalogSidebar Categories="@_categories"
                        OnFiltersApplied="HandleFiltersApplied"
                        OnFiltersCleared="HandleFiltersCleared" />

        <main class="catalog-main">
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@(_pagedResult?.TotalCount ?? 0)"
                            Page="@_currentPage"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            @if (_loading)
            {
                <div class="catalog-loading">
                    <p>Loading products…</p>
                </div>
            }
            else if (_pagedResult is null || _pagedResult.Items.Count == 0)
            {
                <ProductGrid Products="@(new List<Product>())"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />
            }
            else
            {
                <ProductGrid Products="@_pagedResult.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />
            }

            <CatalogPagination CurrentPage="@_currentPage"
                               TotalCount="@(_pagedResult?.TotalCount ?? 0)"
                               PageSize="@PageSize"
                               OnPageChanged="HandlePageChanged" />
        </main>
    </div>
}

@code {
    private const int PageSize = 12;

    private List<string> _categories = [];
    private PagedResult<Product>? _pagedResult;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        try
        {
            _error = null;
            _loading = true;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            _pagedResult = await productsTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _error = null;
            _loading = true;
            _pagedResult = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFiltersApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleFiltersCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private Task HandleProductSelected(Product product)
    {
        // Parent page can navigate to detail page
        // NavigationManager.NavigateTo($"/product/{product.Id}");
        return Task.CompletedTask;
    }

    private Task HandleAddToCart(Product product)
    {
        // Handle add-to-cart logic
        return Task.CompletedTask;
    }
}
"}

